type SecondParameter<T extends (...args: never) => unknown> = Parameters<T>[1];

/**
 * @summary This endpoint is for searching the linearization (such as MMS). The search can be customized using the parameters as described
Search endpoint accepts both GET and POST requests. If the size of the request is too large, you may need to use POST
as HTTP GET has a size limit of 2K
 */
export const searchLinearization = (
  releaseId: string,
  linearizationname: string,
  params?: SearchLinearizationParams,
  options?: SecondParameter<typeof medicalRequest<ISearchResult>>,
) => {
  return medicalRequest<ISearchResult>(
    {
      url: `https://id.who.int/icd/release/11/${encodeURIComponent(String(releaseId))}/${encodeURIComponent(String(linearizationname))}/search`,
      method: "GET",
      params,
    },
    options,
  );
};

/**
 * @summary This endpoint returns  information on the category together with its children categories
 */
export const getICD10Entity = (
  releaseId: string,
  code: string,
  options?: SecondParameter<typeof medicalRequest<ICD10Entity>>,
) => {
  return medicalRequest<ICD10Entity>(
    {
      url: `https://id.who.int/icd/release/10/${encodeURIComponent(String(releaseId))}/${encodeURIComponent(String(code))}`,
      method: "GET",
    },
    options,
  );
};

export type SearchLinearizationResult = NonNullable<
  Awaited<ReturnType<typeof searchLinearization>>
>;
export type GetICD10EntityResult = NonNullable<Awaited<ReturnType<typeof getICD10Entity>>>;
